theorem startCursor_config_eq {old new : Config P A D} {refs : ReferenceSet}
    (h : ConfigAgreement old new refs) (world : World P A D) :
    startCursor old world = startCursor new world

theorems.statement:
∀ {P A D : Type} {a b : DefiKernel.Metatheory.ReferenceSet} {first second : DefiKernel.Metatheory.SeqGroup P A D},
  @DefiKernel.Metatheory.SupportedGroup P A D a first →
    @DefiKernel.Metatheory.SupportedGroup P A D b second →
      @DefiKernel.Metatheory.SupportedGroup P A D (a.union b) (@DefiKernel.Metatheory.SeqGroup.seq P A D first second)

theorems.source_statement:
theorem supportedGroup_union_seq {a b : ReferenceSet} {first second : SeqGroup P A D}
    (ha : SupportedGroup a first) (hb : SupportedGroup b second) :
    SupportedGroup (a.union b) (.seq first second)

